pet_000705={can_double_ride=false,can_ride=true,class="萌萌类精灵",description="在深水区偶尔能见到琉璃一般的美丽流光，那便是琉璃君主与同族们随着洋流汇聚，组成宛如浪潮一般的集群。请前往观赏的洛克们注意，它们的触手与毒液十分危险，务必保持距离。",egg_group={13,10},evolution_id="dc5e_31bc8506351842",feature_skill_id="dc5g_5f7d2719d9b986",form="首领形态",game_id=5066,handbook_id="dc5h_d47edc8992f656",has_shiny=false,height="1.6~2M",id="pet_000705",image={has_egg=false,has_fruit=false,head="PetAvatar_4094.png",illustration="PetPortrait_ShuiMuBo.png"},is_lord_evolution=true,learnset_id="dc5l_430c9cbcc1abc6",move_type="浮游",name="琉璃君主",number="245",perception_range=40,relation_key="水系|毒系",release={date="2026-11-05"},review_gold=4000,siblings={"pet_000109"},stage=4,starlight=80,stats={atk=40,def=93,hp=141,spa=89,spd=136,spe=95},title="琉璃君主",types={"水系","毒系"},weight="133~215KG"},
pet_000706={can_double_ride=true,can_ride=true,class="自然类精灵",description="在冰面上挥动沉重的晶体化武器并不简单，不过头上戴一顶很重的圣冠倒是有助于平衡重心。于是它不再低头，因为圣冠会掉。",egg_group={13,10},evolution_id="dc5e_98ec5af7fd2283",feature_skill_id="dc5g_41cff7bf405420",form="首领形态",game_id=5067,handbook_id="dc5h_2cab7e25943b27",has_shiny=false,height="1.75~2.3M",id="pet_000706",image={has_egg=false,has_fruit=false,head="PetAvatar_4110.png",illustration="PetPortrait_BuLuSiBo.png"},is_lord_evolution=true,learnset_id="dc5l_ebd721f4fa7464",move_type="地面",name="圣冠布鲁斯",number="254",perception_range=40,relation_key="冰系",release={date="2026-11-05"},review_gold=4000,siblings={"pet_000217"},stage=4,starlight=80,stats={atk=103,def=114,hp=73,spa=28,spd=88,spe=90},title="圣冠布鲁斯",types={"冰系"},weight="172~270KG"},
pet_000638={can_double_ride=true,can_ride=true,class="自然类精灵",description="天真纯粹的恶、「圣龙博弈」头号玩家、「圣龙乐园」的常驻导游、桀桀坏笑的小混蛋，这些身份不可能同时出现在一个生物身上。 “你说是吧，小冥龙？” “啊？我吗？”",ecology={eggs={{description="完成「圣龙宝藏」赛季作业获得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”，且支持自选性格与个体资质的小冥龙。",icon="Item_150902.png",name="小冥龙的蛋",sources={"完成「圣龙宝藏」赛季作业"}}}},egg_group={1},evolution_id="dc5e_85b1512625efd1",feature_skill_id="dc5g_a28cee20269fdf",game_id=3797,handbook_id="dc5h_23ab6801276790",handbook_show_topics=true,has_shiny=false,height="0.7~0.92M",id="pet_000638",image={egg="Item_150902.png",has_egg=true,has_fruit=false,head="PetAvatar_3797.png",illustration="PetPortrait_MingLong2Ar.png"},learnset_id="dc5l_f9ed31770c32e7",move_type="步行",name="小冥龙",number="469",perception_range=40,relation_key="幽系|龙系",release={date="2026-11-05"},review_gold=4000,siblings={},stage=1,starlight=80,stats={atk=102,def=65,hp=94,spa=34,spd=51,spe=56},title="小冥龙",types={"幽系","龙系"},weight="31~66KG"},
pet_000639={can_double_ride=true,can_ride=true,class="自然类精灵",description="这个世界上从没有过两只冥古龙同时现世，传说当一只冥古龙消失，另一只冥古龙才会出现。灵魂拥有强大的力量但呈现不稳定的特质，据说曾经有一只冥古龙被分割了灵魂，光明的部分被洛克疼爱，阴暗的部分不知所踪……",ecology={acquisition_pet_id="pet_000638"},egg_group={1},evolution_id="dc5e_85b1512625efd1",feature_skill_id="dc5g_a28cee20269fdf",game_id=3798,handbook_id="dc5h_6b12a592e18496",handbook_show_topics=true,has_shiny=false,height="2.2~2.8M",id="pet_000639",image={has_egg=false,has_fruit=false,head="PetAvatar_3798.png",illustration="PetPortrait_MingLong3Ar.png"},learnset_id="dc5l_f9ed31770c32e7",move_type="步行",name="冥古龙",number="470",perception_range=40,relation_key="幽系|龙系",release={date="2026-11-05"},review_gold=4000,siblings={},stage=2,starlight=80,stats={atk=128,def=81,hp=118,spa=42,spd=63,spe=70},title="冥古龙",types={"幽系","龙系"},weight="243~440KG"},
pet_000640={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="地银链在地下暗河里转着圈儿飘来飘去，一刻也停不下来。当它肚子咕咕叫准备回家吃饭的时候，矿工们开始跟着它走，傍晚时分准能找到银矿。如果看到它的银丝开始发黑，矿工就知道进入了有危险的矿道，该往回撤了。",ecology={eggs={{description="购买「圣龙通行证-银脉」闪耀契约礼券获得的珍贵精灵蛋，经过孵化可以得到“异色”外观、“了不起”天分、且支持自选性格、个体资质的地银链。",icon="Item_150875.png",is_shiny=true,name="异色地银链的蛋",sources={"购买「圣龙通行证-银脉」闪耀契约礼券"}}},fruits={{description="通过观察其花纹可以看出，这是地银链的果实。",icon="Item_108258.png",name="地银链的果实",sources={"圣龙通行证获得"},wisdom_tree=false}}},egg_group={1},evolution_id="dc5e_6c81f5c70d9044",feature_skill_id="dc5g_47ab7b3837cb07",game_id=3799,handbook_id="dc5h_fdfd2de051e8c6",handbook_show_topics=true,has_shiny=true,height="0.15~0.33M",id="pet_000640",image={egg="Item_149254.png",fruits={"Item_108258.png"},has_egg=true,has_fruit=true,head="PetAvatar_3799.png",illustration="PetPortrait_DiYinLian1.png",shiny="PetPortrait_DiYinLian1_yise.png",shiny_head="PetAvatar_3799_1.png"},learnset_id="dc5l_58d1c32e695803",move_type="地面",name="地银链",number="471",perception_range=40,relation_key="地系",release={date="2026-11-05"},review_gold=1600,siblings={},stage=1,starlight=32,stats={atk=32,def=49,hp=60,spa=74,spd=72,spe=72},title="地银链",types={"地系"},weight="1.5~3.3KG"},
pet_000641={can_double_ride=true,can_ride=true,catch_threshold={500},class="自然类精灵",description="地底银鳞真的很爱遛弯，撞见了臭臭锥会变黑，路过了铜星人会泛青，它们不觉得痛反而觉得有趣。到了傍晚，咯咯笑着集体钻回暗河洗澡，把一身颜色泡回银白，第二天接着四处冒险。",ecology={acquisition_pet_id="pet_000640"},egg_group={1},evolution_id="dc5e_6c81f5c70d9044",feature_skill_id="dc5g_47ab7b3837cb07",game_id=3800,handbook_id="dc5h_19b523fbe86fdf",handbook_show_topics=true,has_shiny=true,height="0.97~1.65M",id="pet_000641",image={has_egg=false,has_fruit=false,head="PetAvatar_3800.png",illustration="PetPortrait_DiYinLian2.png",shiny="PetPortrait_DiYinLian2_yise.png",shiny_head="PetAvatar_3800_1.png"},learnset_id="dc5l_58d1c32e695803",move_type="地面",name="地底银鳞",number="472",perception_range=40,relation_key="地系",release={date="2026-11-05"},review_gold=2800,siblings={},stage=2,starlight=56,stats={atk=42,def=66,hp=80,spa=98,spd=96,spe=96},title="地底银鳞",types={"地系"},weight="65~105KG"},
pet_000642={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="地绡银龙说，遛弯时候最常遇到的是洛克，洛克们总是灰头土脸，看起来饥肠辘辘，分给他们矿石他们也不吃，真奇怪。拉布朗矿山的老矿工们感受到善意，努力不让地绡银龙扫兴，定期组织一队人马扛着水桶爬到山谷里，帮它搓背。",ecology={acquisition_pet_id="pet_000640"},egg_group={1},evolution_id="dc5e_6c81f5c70d9044",feature_skill_id="dc5g_47ab7b3837cb07",game_id=3801,handbook_id="dc5h_edde2657580089",handbook_show_topics=true,has_shiny=true,height="2.1~4.3M",id="pet_000642",image={has_egg=false,has_fruit=false,head="PetAvatar_3801.png",illustration="PetPortrait_DiYinLian3.png",shiny="PetPortrait_DiYinLian3_yise.png",shiny_head="PetAvatar_3801_1.png"},learnset_id="dc5l_58d1c32e695803",move_type="地面",name="地绡银龙",number="473",perception_range=40,relation_key="地系",release={date="2026-11-05"},review_gold=4000,siblings={},stage=3,starlight=80,stats={atk=53,def=82,hp=100,spa=123,spd=120,spe=120},title="地绡银龙",types={"地系"},weight="340~770KG"},
pet_000643={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="一天里绝大多数时候，沉金兽都在溪水里不动，就算洛克靠近也懒得动弹。水流从它们头顶的金嵴上淌过，会把杂质带走，它们长期泡过的河段，河沙会泛起一层淡淡的金光。",ecology={eggs={{description="购买「圣龙通行证-金山」闪耀契约礼券获得的珍贵精灵蛋，经过孵化可以得到“异色”外观、“了不起”天分、且支持自选性格、个体资质的沉金兽。",icon="Item_150876.png",is_shiny=true,name="异色沉金兽的蛋",sources={"购买「圣龙通行证-金山」闪耀契约礼券"}}},fruits={{description="通过观察其花纹可以看出，这是沉金兽的果实。",icon="Item_108259.png",name="沉金兽的果实",sources={"圣龙通行证获得"},wisdom_tree=false}}},egg_group={1},evolution_id="dc5e_d92e4fbb814ad4",feature_skill_id="dc5g_d6123e8a7d96bf",game_id=3802,handbook_id="dc5h_331f9488973b5f",handbook_show_topics=true,has_shiny=true,height="0.55~0.7M",id="pet_000643",image={egg="Item_149255.png",fruits={"Item_108259.png"},has_egg=true,has_fruit=true,head="PetAvatar_3802.png",illustration="PetPortrait_ChenJinShou1.png",shiny="PetPortrait_ChenJinShou1_yise.png",shiny_head="PetAvatar_3802_1.png"},learnset_id="dc5l_426a728f59c9f4",move_type="地面",name="沉金兽",number="474",perception_range=40,relation_key="电系",release={date="2026-11-05"},review_gold=1600,siblings={},stage=1,starlight=32,stats={atk=79,def=76,hp=87,spa=35,spd=53,spe=48},title="沉金兽",types={"电系"},weight="3.5~6KG"},
pet_000644={can_double_ride=true,can_ride=true,catch_threshold={500},class="自然类精灵",description="龙头金的金嵴在溪流的反复洗滤中，偶尔会漏下一小片金砂，下游常常守着一群洛克王国的工匠，探着头、伸着筛子，急得团团转，而龙头金站在溪水里还是那副不急不慢的样子。",ecology={acquisition_pet_id="pet_000643"},egg_group={1},evolution_id="dc5e_d92e4fbb814ad4",feature_skill_id="dc5g_d6123e8a7d96bf",game_id=3803,handbook_id="dc5h_80a96df6736f1e",handbook_show_topics=true,has_shiny=true,height="0.95~1.43M",id="pet_000644",image={has_egg=false,has_fruit=false,head="PetAvatar_3803.png",illustration="PetPortrait_ChenJinShou2.png",shiny="PetPortrait_ChenJinShou2_yise.png",shiny_head="PetAvatar_3803_1.png"},learnset_id="dc5l_426a728f59c9f4",move_type="地面",name="龙头金",number="475",perception_range=40,relation_key="电系",release={date="2026-11-05"},review_gold=2800,siblings={},stage=2,starlight=56,stats={atk=105,def=102,hp=116,spa=46,spd=70,spe=64},title="龙头金",types={"电系"},weight="97~164KG"},
pet_000645={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="龙嵴金脉常年伏在地下深处，只是打个盹的功夫，一千个昼夜就过去了。它打个大喷嚏，金子四散飞溅；它伸伸懒腰，金子滑落掉到土里，被岁月埋深。卡洛西亚大陆上许多金矿的成因，是它在那里睡过午觉。",ecology={acquisition_pet_id="pet_000643"},egg_group={1},evolution_id="dc5e_d92e4fbb814ad4",feature_skill_id="dc5g_d6123e8a7d96bf",game_id=3804,handbook_id="dc5h_462bef2573e23c",handbook_show_topics=true,has_shiny=true,height="2.1~3.2M",id="pet_000645",image={has_egg=false,has_fruit=false,head="PetAvatar_3804.png",illustration="PetPortrait_ChenJinShou3.png",shiny="PetPortrait_ChenJinShou3_yise.png",shiny_head="PetAvatar_3804_1.png"},learnset_id="dc5l_426a728f59c9f4",move_type="地面",name="龙嵴金脉",number="476",perception_range=40,relation_key="电系",release={date="2026-11-05"},review_gold=4000,siblings={},stage=3,starlight=80,stats={atk=131,def=127,hp=145,spa=58,spd=88,spe=80},title="龙嵴金脉",types={"电系"},weight="830~2000KG"},
pet_000646={can_double_ride=false,can_ride=true,catch_threshold={1000},class="自然类精灵",description="身上的胶质保护层富有弹性，乐乐鲨总会在磕磕碰碰中弹来弹去。喜欢和同伴们嬉戏打闹，享受互相碰撞后被弹飞的乐趣。",ecology={eggs={{description="在「圣龙宝藏」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的乐乐鲨。",icon="Item_150877.png",name="乐乐鲨的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的乐乐鲨。",icon="Item_150894.png",is_shiny=true,name="异色乐乐鲨的蛋"}},fruits={{description="通过观察其花纹可以看出，这是乐乐鲨的果实。",icon="Item_108260.png",name="乐乐鲨的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={13},egg_size={huge_min=869,max=880,min=350,mini_max=361,unit="g"},evolution_id="dc5e_9550958f4bf948",feature_skill_id="dc5g_9493f5a7aa29ff",game_id=3805,handbook_id="dc5h_065106db0a0a0d",handbook_show_topics=true,has_shiny=true,height="0.12~0.23M",id="pet_000646",image={egg="Item_107251.png",fruits={"Item_108260.png"},has_egg=true,has_fruit=true,head="PetAvatar_3805.png",illustration="PetPortrait_AWaSha1_002.png",shiny="PetPortrait_AWaSha1_002_yise.png",shiny_head="PetAvatar_3805_1.png"},learnset_id="dc5l_8834c6ceebcb91",move_type="浮游",name="乐乐鲨",number="477",perception_range=40,relation_key="水系",release={date="2026-11-05"},review_gold=1200,siblings={},stage=1,starlight=24,stats={atk=94,def=96,hp=98,spa=37,spd=70,spe=76},title="乐乐鲨",types={"水系"},weight="1~2.2KG"},
pet_000647={can_double_ride=false,can_ride=true,catch_threshold={250},class="自然类精灵",description="会把还没长出保护层的乐乐鲨带在身边，遇到危险时将它们含进嘴巴里，等待状况安全后再吐出来。如果判断对方不是特别危险，也会让强壮的乐乐鲨一同战斗，以此锻炼它们的能力。",ecology={acquisition_pet_id="pet_000646"},egg_group={13},egg_size={huge_min=869,max=880,min=350,mini_max=361,unit="g"},evolution_id="dc5e_744e21f436cf82",feature_skill_id="dc5g_9493f5a7aa29ff",form="柠檬鲨的样子",game_id=3806,handbook_id="dc5h_0b598f4df8985b",handbook_show_topics=true,has_shiny=true,height="0.38~0.65M",id="pet_000647",image={egg="Item_107251.png",fruits={"Item_108260.png"},has_egg=true,has_fruit=true,head="PetAvatar_3806.png",illustration="PetPortrait_AWaSha1_001.png",shiny="PetPortrait_AWaSha1_001_yise.png",shiny_head="PetAvatar_3806_1.png"},learnset_id="dc5l_a5f6d72200c08b",move_type="浮游",name="阿瓦鲨",number="478",perception_range=40,relation_key="水系",release={date="2026-11-05"},review_gold=3000,siblings={"pet_000648"},stage=2,starlight=60,stats={atk=117,def=120,hp=123,spa=46,spd=88,spe=95},title="阿瓦鲨（柠檬鲨的样子）",types={"水系"},weight="9~15KG"},
pet_000648={can_double_ride=false,can_ride=true,catch_threshold={250},class="自然类精灵",description="有东西在动？咬一口。有洛克经过？咬一口。有颗可可果？咬一口。牙被崩掉了？咬一口。无所谓，总之先咬一口。",ecology={acquisition_pet_id="pet_000646"},egg_group={13},egg_size={huge_min=869,max=880,min=350,mini_max=361,unit="g"},evolution_id="dc5e_8106f92a8d96e6",feature_skill_id="dc5g_9493f5a7aa29ff",form="虎纹鲨的样子",game_id=3807,handbook_id="dc5h_0b598f4df8985b",has_shiny=true,height="0.38~0.65M",id="pet_000648",image={egg="Item_107251.png",fruits={"Item_108260.png"},has_egg=true,has_fruit=true,head="PetAvatar_3807.png",illustration="PetPortrait_AWaSha1Ar.png",shiny="PetPortrait_AWaSha1Ar_yise.png",shiny_head="PetAvatar_3807_1.png"},learnset_id="dc5l_78b093b4c028c0",move_type="浮游",name="阿瓦鲨",number="478",perception_range=40,relation_key="水系",release={date="2026-11-05"},review_gold=3000,siblings={"pet_000647"},stage=2,starlight=60,stats={atk=146,def=120,hp=90,spa=57,spd=88,spe=95},title="阿瓦鲨（虎纹鲨的样子）",types={"水系"},weight="9~13.6KG"},
pet_000649={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="长长的脚丫支起小小的蛋壳，蛋包蛋高高地扬起头，梦想着自己飞翔的模样。因为破开蛋壳的鸟儿总要飞向天空，洛克们都是这么说的。在天空中究竟会看到什么呢，大地又是什么模样呢？",ecology={eggs={{description="在「圣龙宝藏」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的蛋包蛋。",icon="Item_150878.png",name="蛋包蛋的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的蛋包蛋。",icon="Item_150895.png",is_shiny=true,name="异色蛋包蛋的蛋"}},fruits={{description="通过观察其花纹可以看出，这是蛋包蛋的果实。",icon="Item_108261.png",name="蛋包蛋的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={6,5},egg_size={huge_min=1059,max=1072,min=445,mini_max=458,unit="g"},evolution_id="dc5e_0047aa720c2960",feature_skill_id="dc5g_4b4900ae57855a",game_id=3808,handbook_id="dc5h_e4727e3c6340e3",handbook_show_topics=true,has_shiny=true,height="0.26~0.4M",id="pet_000649",image={egg="Item_107252.png",fruits={"Item_108261.png"},has_egg=true,has_fruit=true,head="PetAvatar_3808.png",illustration="PetPortrait_DanBaoDan1.png",shiny="PetPortrait_DanBaoDan1_yise.png",shiny_head="PetAvatar_3808_1.png"},learnset_id="dc5l_365748efa9e56e",move_type="地面",name="蛋包蛋",number="479",perception_range=40,relation_key="普通系|萌系",release={date="2026-11-05"},review_gold=1200,siblings={},stage=1,starlight=24,stats={atk=77,def=91,hp=96,spa=76,spd=69,spe=52},title="蛋包蛋",types={"普通系","萌系"},weight="1.27~2.68KG"},
pet_000650={can_double_ride=true,can_ride=true,catch_threshold={500},class="自然类精灵",description="为什么鸡麻麻不再向往天空呢？因为啊，鸡麻麻曾经飞得很高，发现地面就像一颗巨大的精灵蛋。如果我飞走了，谁来照料这颗精灵蛋呢？所以呢，鸡麻麻就落回到地面啦。",ecology={acquisition_pet_id="pet_000649",activities={{name="命定花种",note="花种出没·战斗后可捕捉",window="2026-12-18 ~ 2026-12-31"}},destined_flower={nature="踏实"}},egg_group={6,5},egg_size={huge_min=1059,max=1072,min=445,mini_max=458,unit="g"},evolution_id="dc5e_0047aa720c2960",feature_skill_id="dc5g_4b4900ae57855a",game_id=3809,handbook_id="dc5h_85e19da705262a",handbook_show_topics=true,has_shiny=true,height="1.51~2.06M",id="pet_000650",image={egg="Item_107252.png",fruits={"Item_108261.png"},has_egg=true,has_fruit=true,head="PetAvatar_3809.png",illustration="PetPortrait_DanBaoDan3.png",shiny="PetPortrait_DanBaoDan3_yise.png",shiny_head="PetAvatar_3809_1.png"},learnset_id="dc5l_365748efa9e56e",move_type="地面",name="鸡麻麻",number="480",perception_range=40,relation_key="普通系|萌系",release={date="2026-11-05"},review_gold=3000,siblings={},stage=2,starlight=60,stats={atk=96,def=113,hp=120,spa=95,spd=86,spe=65},title="鸡麻麻",types={"普通系","萌系"},weight="70~117KG"},
pet_000651={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="性格胆小警惕，总是试图躲藏起来。但听到富有节奏感的音乐时，总是会忍不住从沙堆中探头围观，悄悄记住那些音乐的节拍。",ecology={eggs={{description="在「圣龙宝藏」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的蟹蟹椰。",icon="Item_150879.png",name="蟹蟹椰的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的蟹蟹椰。",icon="Item_150896.png",is_shiny=true,name="异色蟹蟹椰的蛋"}},fruits={{description="通过观察其花纹可以看出，这是蟹蟹椰的果实。",icon="Item_108262.png",name="蟹蟹椰的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={7,3},egg_size={huge_min=553,max=560,min=210,mini_max=217,unit="g"},evolution_id="dc5e_fcd6f3acd80b87",feature_skill_id="dc5g_7a381e26cb5589",game_id=3810,handbook_id="dc5h_f72705b762f0c8",handbook_show_topics=true,has_shiny=true,height="0.29~0.41M",id="pet_000651",image={egg="Item_107253.png",fruits={"Item_108262.png"},has_egg=true,has_fruit=true,head="PetAvatar_3810.png",illustration="PetPortrait_YeMiaoXie1.png",shiny="PetPortrait_YeMiaoXie1_yise.png",shiny_head="PetAvatar_3810_1.png"},learnset_id="dc5l_f9ef77bfa2561b",move_type="地面",name="蟹蟹椰",number="481",perception_range=40,relation_key="水系|草系",release={date="2026-11-05"},review_gold=1600,siblings={},stage=1,starlight=32,stats={atk=102,def=110,hp=108,spa=43,spd=81,spe=68},title="蟹蟹椰",types={"水系","草系"},weight="0.6~1.4KG"},
