pet_000653={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="通常生活在寒冷的水域，在冰冷的洋流中无忧无虑地摇曳，饶有兴趣地观察深蓝世界中的一切。接下来会随着洋流去向哪里呢？鲸羽飘摇着，期待着下一个惊喜。",ecology={eggs={{description="在「圣龙宝藏」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的鲸羽。",icon="Item_150880.png",name="鲸羽的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的鲸羽。",icon="Item_150897.png",is_shiny=true,name="异色鲸羽的蛋"}},fruits={{description="通过观察其花纹可以看出，这是鲸羽的果实。",icon="Item_108263.png",name="鲸羽的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={13,7},egg_size={huge_min=1464,max=1480,min=700,mini_max=716,unit="g"},evolution_id="dc5e_60db7dce6beee5",feature_skill_id="dc5g_6d97280cf52454",game_id=3812,handbook_id="dc5h_9baf378f7969ae",handbook_show_topics=true,has_shiny=true,height="0.26~0.39M",id="pet_000653",image={egg="Item_107254.png",fruits={"Item_108263.png"},has_egg=true,has_fruit=true,head="PetAvatar_3812.png",illustration="PetPortrait_YuJing1.png",shiny="PetPortrait_YuJing1_yise.png",shiny_head="PetAvatar_3812_1.png"},learnset_id="dc5l_0e1b9bf8ce14df",move_type="地面",name="鲸羽",number="483",perception_range=40,relation_key="幻系|冰系",release={date="2026-11-05"},review_gold=1600,siblings={},stage=1,starlight=32,stats={atk=30,def=58,hp=108,spa=99,spd=82,spe=80},title="鲸羽",types={"幻系","冰系"},weight="2~3.7KG"},
