pet_000655={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="小小的豆粒鹅总是充满大大的能量，似乎永远都在蹦蹦跳跳、吵吵闹闹……尽管它们尚且弱小，依旧喜欢站在亲近的洛克头上，用喋喋不休的鸣叫宣誓自己的存在。",ecology={eggs={{description="在「圣龙宝藏」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的豆粒鹅。",icon="Item_150881.png",name="豆粒鹅的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的豆粒鹅。",icon="Item_150898.png",is_shiny=true,name="异色豆粒鹅的蛋"}},fruits={{description="通过观察其花纹可以看出，这是豆粒鹅的果实。",icon="Item_108264.png",name="豆粒鹅的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={6,5},egg_size={huge_min=656,max=664,min=280,mini_max=288,unit="g"},evolution_id="dc5e_e8c9bdd058f20a",feature_skill_id="dc5g_6f3fd4c4b72291",game_id=3814,handbook_id="dc5h_e117943ed7a772",handbook_show_topics=true,has_shiny=true,height="0.15~0.25M",id="pet_000655",image={egg="Item_107255.png",fruits={"Item_108264.png"},has_egg=true,has_fruit=true,head="PetAvatar_3814.png",illustration="PetPortrait_DouLiE1.png",shiny="PetPortrait_DouLiE1_yise.png",shiny_head="PetAvatar_3814_1.png"},learnset_id="dc5l_c94f4208974e41",move_type="地面",name="豆粒鹅",number="485",perception_range=40,relation_key="冰系",release={date="2026-11-05"},review_gold=1200,siblings={},stage=1,starlight=24,stats={atk=77,def=107,hp=102,spa=69,spd=72,spe=76},title="豆粒鹅",types={"冰系"},weight="0.8~1.66KG"},
pet_000656={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="为了保护调皮吵闹的豆粒鹅们，仔细挑选了松软的白雪堆在身上，搭起清凉又蓬松的雪巢穴。有些洛克因此受到启发，创造出口感松软绵密的特色冰雪甜品，在炎热的季节广受好评。",ecology={acquisition_pet_id="pet_000655",activities={{name="命定花种",note="花种出没·战斗后可捕捉",window="2026-11-20 ~ 2026-12-04"}},destined_flower={nature="平和"}},egg_group={6,5},egg_size={huge_min=656,max=664,min=280,mini_max=288,unit="g"},evolution_id="dc5e_e8c9bdd058f20a",feature_skill_id="dc5g_6f3fd4c4b72291",game_id=3815,handbook_id="dc5h_5f77beda3c4fd0",handbook_show_topics=true,has_shiny=true,height="1.39~1.6M",id="pet_000656",image={egg="Item_107255.png",fruits={"Item_108264.png"},has_egg=true,has_fruit=true,head="PetAvatar_3815.png",illustration="PetPortrait_DouLiE3.png",shiny="PetPortrait_DouLiE3_yise.png",shiny_head="PetAvatar_3815_1.png"},learnset_id="dc5l_c94f4208974e41",move_type="地面",name="刨雪鹅",number="486",perception_range=40,relation_key="冰系",release={date="2026-11-05"},review_gold=3000,siblings={},stage=2,starlight=60,stats={atk=96,def=134,hp=127,spa=87,spd=90,spe=95},title="刨雪鹅",types={"冰系"},weight="97.3~175KG"},
pet_000657={can_double_ride=false,can_ride=true,catch_threshold={1000},class="自然类精灵",description="背上的果肉富有营养，饱含甜丝丝的果汁。西瓜虫趴在地上休息时，常常因为不起眼的体型而被忽略。洛克们不小心踩到的话很容易滑倒，千万要注意。",ecology={eggs={{description="在「圣龙宝藏」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的西瓜虫。",icon="Item_150882.png",name="西瓜虫的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的西瓜虫。",icon="Item_150899.png",is_shiny=true,name="异色西瓜虫的蛋"}},fruits={{description="通过观察其花纹可以看出，这是西瓜虫的果实。",icon="Item_108265.png",name="西瓜虫的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={4,8},egg_size={huge_min=592,max=600,min=210,mini_max=218,unit="g"},evolution_id="dc5e_7bede4dbd340d7",feature_skill_id="dc5g_17a2b9c92c32da",game_id=3816,handbook_id="dc5h_d3e2d4331dd578",handbook_show_topics=true,has_shiny=true,height="0.21~0.33M",id="pet_000657",image={egg="Item_107256.png",fruits={"Item_108265.png"},has_egg=true,has_fruit=true,head="PetAvatar_3816.png",illustration="PetPortrait_XiGuaChong1.png",shiny="PetPortrait_XiGuaChong1_yise.png",shiny_head="PetAvatar_3816_1.png"},learnset_id="dc5l_37ced87185820c",move_type="地面",name="西瓜虫",number="487",perception_range=40,relation_key="虫系|草系",release={date="2026-11-05"},review_gold=1200,siblings={},stage=1,starlight=24,stats={atk=50,def=61,hp=86,spa=100,spd=103,spe=64},title="西瓜虫",types={"虫系","草系"},weight="0.6~1.5KG"},
