pet_000661={can_double_ride=false,can_ride=true,catch_threshold={1000},class="自然类精灵",description="魔法学院的期末到来时，有些小洛克会借助它们旋转时出现的斑点数量来做出命运的抉择——但其实滴溜豚们大多有着严重的选择困难症，连它们自己都不知道该选什么。",ecology={eggs={{description="在「圣龙宝藏」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的滴溜豚。",icon="Item_150884.png",name="滴溜豚的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的滴溜豚。",icon="Item_150901.png",is_shiny=true,name="异色滴溜豚的蛋"}},fruits={{description="通过观察其花纹可以看出，这是滴溜豚的果实。",icon="Item_108267.png",name="滴溜豚的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={13},egg_size={huge_min=1187,max=1200,min=525,mini_max=539,unit="g"},evolution_id="dc5e_358574fd0eaab8",feature_skill_id="dc5g_b94c4ce38083a1",game_id=3820,handbook_id="dc5h_f824226a9f86d9",handbook_show_topics=true,has_shiny=true,height="0.15~0.3M",id="pet_000661",image={egg="Item_107258.png",fruits={"Item_108267.png"},has_egg=true,has_fruit=true,head="PetAvatar_3820.png",illustration="PetPortrait_DiLiuTun1.png",shiny="PetPortrait_DiLiuTun1_yise.png",shiny_head="PetAvatar_3820_1.png"},learnset_id="dc5l_2bb858d471c8a5",move_type="地面",name="滴溜豚",number="491",perception_range=40,relation_key="毒系|幻系",release={date="2026-11-05"},review_gold=1600,siblings={},stage=1,starlight=32,stats={atk=89,def=73,hp=91,spa=89,spd=98,spe=80},title="滴溜豚",types={"毒系","幻系"},weight="1.5~3KG"},
